List<int> getBinaryRepresentation(String opCode) {
  int value = int.parse(opCode.substring(1));
  return [value >> 7 & 1, value >> 6 & 1, value >> 5 & 1,
          value >> 4 & 1, value >> 3 & 1, value >> 2 & 1,
          value >> 1 & 1, value & 1];
}

// Convert binary string to integer.
int decodeBinaryString(String binStr) {
  int result = 0;
  for (int i = 0; i < binStr.length; i++) {
    result *= 2;
    result += int.parse(binStr[i]);
  }
  return result;
}

fn0(List<List<String>> instructions) {
