        break;

      case "ADD":
        output.addAll(getBinaryRepresentation("2" + operand[0].toString()));
        break;

      case "SUB":
        output.addAll(getBinaryRepresentation("3" + operand[0].toString()));
        break;

      default:
        throw Exception('Invalid operation code.');
    }
  }

  return output.map((bit) => bit.toString()).join('');
