  final code = <int>[];

  for (final line in input) {
    if (line.trim().isEmpty) continue;

    final tokens = line.split(' ');
    final opCode = int.parse(tokens[0]);

    switch (opCode) {
      case 1:
        // ADD Rn, Rm
        final regN = int.parse(tokens[1][1]) - 'A'.codeUnits.first;
        final regM = int.parse(tokens[2][1]) - 'A'.codeUnits.first;

        code.add(0x48);
        code.add(regN & 0xf);
        code.add(regM & 0xf);
        break;

      case 2:
        // SUB Rn, Rm
        final regN = int.parse(tokens[1][1]) - 'A'.codeUnits.first;
        final regM = int.parse(tokens[2][1]) - 'A'.codeUnits.first;

        code.add(0x58);
        code.add(regN & 0xf);
        code.add(regM & 0xf);
        break;

      case 3:
        // MOV Rn, #immediate
        final regN = int.parse(tokens[1][1]) - 'A'.codeUnits.first;
        final val = int.parse(tokens[2].substring(2));

        code.add(0x60 | ((regN << 4) & 0xf0));
        code.add(val & 0xff);
        break;

      case 4:
        // B label
        final label = tokens[1];

        code.add(0xe9);
        code.add((label.codeUnits.first * 2 + 1).toByte());
        code.add(label.codeUnits.last.toByte());
        break;

      case 5:
        // BLX PC, offset
        final offset = int.parse(tokens[1]);

        code.add(0xea);
        code.add(((offset >> 8) & 0xff).toByte());
        code.add((offset & 0xff).toByte());
        break;

      default:
        throw UnsupportedError("Unsupported instruction");
    }
  }

  stdout.writeBytes(code);
}
