        } else {
          print("Stack underflow");
        }
        break;
      case "ADD":
        if (stack.length >= 2) {
          val2 = stack.removeLast();
          val1 = stack.removeLast();
          stack.add(val1 + val2);
        } else {
          print("Not enough elements on the stack");
        }
        break;
      case "SUB":
        if (stack.length >= 2) {
          val2 = stack.removeLast();
          val1 = stack.removeLast();
          stack.add(val1 - val2);
        } else {
          print("Not enough elements on the stack");
        }
        break;
      case "MUL":
        if (stack.length >= 2) {
          val2 = stack.removeLast();
          val1 = stack.removeLast();
          stack.add(val1 * val2);
        } else {
          print("Not enough elements on the stack");
