int fn0(List<int> list, int index) {
  if (index < 0 || index >= list.length) return -1;

  // Check if the element at [index] is even or odd.
  final remainder = list[index] % 2;

  // If it's even, we need to check both next and previous elements for their parity.
  if (remainder == 0) {
    // Get the next element after current one (if exists)
    final nextIndex = index + 1;
    if (nextIndex < list.length && list[nextIndex] % 2 == 0) {
      return nextIndex; // Next element is also even
    } else {
      // No next even found, so look in reverse direction from current position
      var prevIndex = index - 1;
      while (prevIndex >= 0) {
        if (list[prevIndex] % 2 == 0) {
          return prevIndex;
        }
        prevIndex--;
      }
      return -1; // No even number found in either direction
    }
  } else { // Odd number at given index
    // Find nearest even on left side of index
    var i = index - 1;
    while (i >= 0) {
      if (list[i] % 2 == 0) {
        return i;
      }
      i--;
    }

    // Not found on left, check right side now
    i = index + 1;
    while (i < list.length) {
      if (list[i] % 2 == 0) {
        return i;
      }
      i++;
    }

    return -1; // No even number found anywhere
  }
}
