  if (lines.isEmpty) return '';

  // Initialize a list to hold the processed instructions
  List<String> dartCode = [];

  for (final line in lines) {
    // Trim leading/trailing whitespace
    final trimmedLine = line.trim();

    // Check if it's a label definition
    if (trimmedLine.startsWith(':')) {
      final labelName = trimmedLine.substring(1).trim(); // Remove colon and trim
      dartCode.add('const $labelName = true;');
    } else if (trimmedLine.contains('=')) {
      // Handle assignment operations like x=2 or x=y+3 etc.
      final parts = trimmedLine.split('=');
      final leftSide = parts[0].trim();
      final rightSide = parts[1].trim();

      // Add variable declaration with default value of 0
      dartCode.add('int ${leftSide} = 0;'); 

      // Replace variables on the right side with their names
      final processedRightSide = replaceVariables(rightSide, dartCode);
      dartCode.add('${leftSide} = $processedRightSide;');
    }
  }

  return dartCode.join('\n');
}

// Helper function to replace variables in an expression
String replaceVariables(String expr, List<String> dartCode) {
  final tokens = expr.split(/([+\-*/%<>&|^~])|(?=[\(\)])/); // Tokenize by operators and parentheses

  // Map to keep track of used variables for checking existing declarations
  final usedVariables = Set<String>();

  for (var i = 0; i < tokens.length; i++) {
    final token = tokens[i];

    // If the token is a variable name
    if (!token.isEmpty && !RegExp(r'[\W_]').hasMatch(token) && !['+', '-', '*', '/', '%', '<', '>', '&', '|', '^', '~'].contains(token)) {
      // Skip if already declared
      if (usedVariables.contains(token)) continue;

      // Declare variable with initial value 0
      dartCode.add('int $token = 0;');
      usedVariables.add(token);
    }
  }

  // Join tokens back together
  return tokens.join('');
}
