int _convertFromBinary(String binaryStr) {
  final bits = binaryStr.split('').map(int.tryParse).where((v) => v != null).toList();

  // Determine the sign bit
  bool isNegative = false;
  if (bits.isNotEmpty && bits[0] == 1) {
    isNegative = true;
    bits.removeAt(0); // Remove sign bit before processing
  }

  // Calculate magnitude using bitwise operations
  int magnitude = 0;
  for (int i = 0; i < bits.length; i++) {
    magnitude += (bits[i] << (bits.length - 1 - i));
  }

  return isNegative ? -magnitude : magnitude;
}
