Future<void> bfsTraversal(int startNode, int endNode) async {
  final Set<int> visited = {startNode};
  final Queue<int> queue = Queue();
  queue.add(startNode);

  while (!queue.isEmpty) {
    final int current = queue.removeFirst();

    if (current == endNode) return;

    for (int neighbor in graph[current] ?? []) {
      if (!visited.contains(neighbor)) {
        visited.add(neighbor);
        queue.add(neighbor);
      }
    }
  }

  throw Exception('No path found from $startNode to $endNode.');
}
