class BinaryToHexConverter {
  final List<int> _bits;

  BinaryToHexConverter(this._bits);

  String convertToHex() {
    if (_bits.isEmpty) return '';

    int bytesCount = (_bits.length + 7) ~/ 8; // Calculate number of bytes needed
    List<int> paddedBits = List.of(_bits)..addAll(List.filled((bytesCount * 8 - _bits.length), 0));

    List<String> hexChars = [];
    for (int i = 0; i < bytesCount; i++) {
      int byteValue = 0;
      for (int j = 0; j < 8 && i * 8 + j < paddedBits.length; j++) {
        byteValue += paddedBits[i * 8 + j] << (7 - j); // Build each bit into the byte value
