import 'dart:io';

// Function to convert assembly instructions into machine code.
fn0(List<String> asm) {
  // Mapping of opcodes and their corresponding binary representations.
  Map<String, String> opcodeMap = {
    "ADD": "1000",
    "SUB": "1001",
    "AND": "1010",
    "ORR": "1011",
    "NOT": "1100",
    "XOR": "1101",
    "SHL": "1110",
    "SAR": "1111"
  };

  List<int> result = [];

  for (String line in asm) {
    if (line.trim().isEmpty || line.startsWith(';')) continue;

    String[] parts = line.split(' ');
    String opCode = parts[0];

    if (!opcodeMap.containsKey(opCode)) {
      throw Exception("Unknown instruction: $opCode");
    }

    int regCount = 3;
    switch (opCode) {
      case "NOT":
        regCount = 2;
        break;
      default:
        regCount = 3;
    }

    if (parts.length != regCount + 1) {
      throw Exception("Invalid number of operands for $opCode");
    }

    // Convert each operand to its register index representation (e.g., R0 -> 0)
    List<int> regs = [];
    for (int i = 1; i < parts.length; i++) {
      if (parts[i].startsWith('R') && parts[i].length == 2) {
        int rIndex = int.parse(parts[i][1]);
        if (rIndex >= 8) {
          throw Exception("Register out of range: ${parts[i]}");
        }
        regs.add(rIndex);
      } else {
        throw Exception("Invalid register name: ${parts[i]}");
      }
    }

    // Construct the binary instruction
    String binOpCode = opcodeMap[opCode]!;
    String binRegs = '';
    for (int idx in regs) {
      binRegs += idx.toString(2).padLeft(3, '0');
    }

    String binInstr = binOpCode + binRegs;
    int value = int.parse(binInstr, radix: 2);

    result.add(value);
  }

  return result;
}
