import 'dart:io';
import 'dart:convert';

void main() {
  final stdin = stdin;
  final stdout = stdout;

  void processInput(String input) {
    if (input.isEmpty) return;

    // Process the input to get binary data and output
    List<int> binaryData = List<int>.from(input.codeUnits);

    // Convert each byte in the binary data into a Dart function call with specific parameters.
    for (int i = 0; i < binaryData.length; ++i) {
      int b = binaryData[i];

      // Determine which instruction type this is based on the first bit of the byte.
      bool isFunctionCall = ((b >> 7) & 1) == 1;
      bool isParameterList = ((b >> 6) & 1) == 1;
      bool isReturnStatement = ((b >> 5) & 1) == 1;
      bool isVariableDeclaration = ((b >> 4) & 1) == 1;

      // If it's an instruction, handle accordingly
      if (!isFunctionCall && !isParameterList && !isReturnStatement && !isVariableDeclaration) {
        print('Invalid instruction');
        continue;
      }

      // Handle functions calls by extracting parameters from remaining bits
      if (isFunctionCall) {
        // Extract the function name
        String funcName = '';
        for (int j = 3; j >= 0; --j) {
          int nextByteIndex = i + j;
          if (nextByteIndex > binaryData.length - 1) break;
          funcName += String.fromCharCode(binaryData[nextByteIndex]);
        }

        // Extract parameter values
        List<String> params = [];
        int paramStartIndex = i + 4;
        while (paramStartIndex <= binaryData.length - 1) {
          int pVal = binaryData[paramStartIndex];
          params.add(pVal.toString());
          paramStartIndex++;
        }

        // Create the dart function call
        String fnCall = '${funcName}(${params.join(', ')})';

        // Output the generated code
        stdout.write(fnCall + '\n');
      } else if (isParameterList) {
        // This is part of a function declaration or variable assignment
        // For example: Function f(a, b)
        // Or var x = ...;
        stdout.write('var ${String.fromCharCode(b)} = ');
      } else if (isReturnStatement) {
        stdout.write('return ');
      } else if (isVariableDeclaration) {
        stdout.write('${String.fromCharCode(b)} = ');
      }
    }
  }

  stdin.transform(utf8.decoder).listen(processInput);
}
