import 'dart:io';
import 'package:collection/collection.dart';

void main() {
  final input = stdin.readLinesSync();
  final instructions = List<String>.from(input);

  int register = 0;
  Map<int, int> memory = {};
  int output = 0;

  for (int i = 0; i < instructions.length; i++) {
    if (instructions[i] == '') continue;

    String op = instructions[i].split(' ')[0];

    switch (op) {
      case 'add':
        // add [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        register += value;
        break;

      case 'mul':
        // mul [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        register *= value;
        break;

      case 'div':
        // div [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        if (value != 0) register ~/= value;
        else throw Exception("Division by zero");
        break;

      case 'mod':
        // mod [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        if (value != 0) register %= value;
        else throw Exception("Modulo by zero");
        break;

      case 'set':
        // set [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        register = value;
        break;

      case 'get':
        // get [address]
        final address = int.parse(instructions[i].split(' ')[1]);
        register = memory[address] ?? 0;
        break;

      case 'store':
        // store [address]
        final address = int.parse(instructions[i].split(' ')[1]);
        memory[address] = register;
        break;

      case 'jump':
        // jump [offset]
        final offset = int.parse(instructions[i].split(' ')[1]);
        i += offset - 1;
        continue;

      case 'jumpeq':
        // jumpeq [offset] [reg]
        final offset = int.parse(instructions[i].split(' ')[1]);
        final reg = int.parse(instructions[i].split(' ')[2]);
        if (register == reg) {
          i += offset - 1;
          continue;
        }
        break;

      case 'jmpneq':
        // jmpneq [offset] [reg]
        final offset = int.parse(instructions[i].split(' ')[1]);
        final reg = int.parse(instructions[i].split(' ')[2]);
        if (register != reg) {
          i += offset - 1;
          continue;
        }
        break;

      case 'inc':
        // inc [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        register++;
        break;

      case 'dec':
        // dec [value]
        final value = int.parse(instructions[i].split(' ')[1]);
        register--;
        break;

      default:
        print('Unknown instruction');
    }

    output = register;
  }
}
