  String currentLabel = '';
  int pc = 0; // Program counter

  for (int i = 0; i < tokens.length; i++) {
    if (tokens[i] == '(') {
      isLabel = true;
      currentLabel = '';
      continue;
    } else if (tokens[i] == ')') {
      isLabel = false;
      instructions.add({'type': 'label', 'name': currentLabel});
      continue;
    } else if (isLabel) {
      currentLabel += tokens[i];
    } else {
      // Handle opcodes here based on tokens
      // For simplicity, we'll assume that the instruction format is "opcode arg1 arg2"

      // Check if it's an opcode with two arguments
      if (i + 2 < tokens.length && tokens[i+1].startsWith('?')) {
        // Opcode with one argument
        instructions.add({
          'type': 'op',
          'opcode': tokens[i],
          'arg1': tokens[i+1]
        });

        i += 2;
      } else if (i + 3 < tokens.length && tokens[i+1].startsWith('?') && tokens[i+2].startsWith('?')) {
        // Opcode with two arguments
        instructions.add({
          'type': 'op',
          'opcode': tokens[i],
          'arg1': tokens[i+1],
          'arg2': tokens[i+2]
        });

        i += 3;
      }
    }

    pc++;
  }

  // Convert instructions to machine code
  List<int> machineCode = [];
  for (var inst in instructions) {
    if (inst['type'] == 'label') {
      // Labels are not included in machine code
      continue;
    } else {
      // Convert opcodes to binary codes
      switch(inst['opcode']) {
        case '?':
          machineCode.add(0x0);
          break;
        case '@':
          machineCode.add(0x1);
          break;
        default:
          throw Exception("Unknown opcode");
      }

      // Add arguments as bytes or immediate values
      if (inst.containsKey('arg1')) {
        var arg1 = inst['arg1'];
        // Assume all arguments are numeric for this example
        machineCode.add(int.parse(arg1));
      }

      if (inst.containsKey('arg2')) {
        var arg2 = inst['arg2'];
        machineCode.add(int.parse(arg2));
      }
    }
  }

  // Output the resulting binary data
