  final input = stdin.readLinesSync().map((line) => line.trim()).toList();

  int index = 0;
  void parseInstruction(int pc, List<int> mem) {
    if (pc >= mem.length || pc < 0) return;

    var opCode = (mem[pc] & 0b1111111110000000) >> 12; // Extract opcode
    var A = (mem[pc] & 0b0000000001111111) >> 6;      // Extract register A
    var B = (mem[pc] & 0x3F);                        // Extract register B

    switch(opCode) {
      case 0:
        // LDA - Load address from memory to accumulator
        mem[A] = mem[B];
        break;

      case 1:
        // ADD - Add value at B into accumulator and store in A
        mem[A] += mem[B];
        break;

      case 2:
        // OR - Bitwise OR of values at B with accumulator and save in A
        mem[A] |= mem[B];
        break;

      case 3:
        // AND - Bitwise AND of values at B with accumulator and save in A
        mem[A] &= mem[B];
        break;

      case 4:
        // XOR - Bitwise XOR of values at B with accumulator and save in A
        mem[A] ^= mem[B];
        break;

      case 5:
        // NOT - Invert bits of the value at B and save in A
        mem[A] = ~mem[B];
        break;

      case 6:
        // JMP - Jump to address stored at B
        pc = B + 1;
        continue;

      case 7:
        // JMPI - Jump to address stored at B if accumulator is zero
        if (mem[A] == 0)
          pc = B + 1;
        break;

      case 8:
        // JPN - Jump to address stored at B if accumulator is negative
        if (mem[A] < 0)
          pc = B + 1;
        break;

      case 9:
        // HLT - Halts execution
        exit(0);

      default:
        print('Unknown instruction');
    }

    pc++;
  }

  while (true) {
    parseInstruction(index, input.map(int.parse).toList());
