// Helper function to compute the binary representation of a number as a list of bits
List<int> getBinaryBits(int n) {
  List<int> bits = [];
  int num = abs(n);
  do {
    if (num % 2 == 0) {
      bits.add(0);
    } else {
      bits.add(1);
    }
    num ~/= 2;
  } while (num > 0);

  // Reverse the bits to match the correct order
  bits = bits.reversed.toList();
  return bits;
}

// Function that takes an integer and returns its binary string with leading zeros to make it exactly 8 digits long
String formatToEightBit(int input) {
  var bitList = getBinaryBits(input); 
  var paddedList = List.generate(8, (_) => 0).filled(8 - bitList.length);
  for (int i = 0; i < bitList.length; i++) {
    paddedList[i + (8 - bitList.length)] = bitList[i];
  }

  String result = '';
  for (var bit in paddedList) {
    result += bit.toString();
  }
  return result;
}
