int fn0(List<int> a) {
  int n = a.length;
  if (n == 0) return 0;

  // Find the maximum value in the array
  var maxVal = a[0];
  for (var i = 1; i < n; ++i) {
    if (a[i] > maxVal) {
      maxVal = a[i];
    }
  }

  // Initialize dp and next_dp arrays
  List<int> dp = List.filled(n, 0);
  List<int> next_dp = List.filled(n, 0);

  // Base case: first element can be taken as one subsequence of length 1
  dp[0] = 1;

  // Iterate through each number from index 1 to end
  for (var i = 1; i < n; ++i) {
    // For current number at index i, check all previous elements j < i
    for (var j = 0; j < i; ++j) {
      if (a[j] < a[i]) {
        next_dp[i] += dp[j]; // Add sequences ending with a[j]
      } else if (a[j] == a[i]) {
        next_dp[i] += dp[j]; // If equal, add sequences that don't include this new sequence since they are same
      }
    }

    // Also account for taking the current number alone
    next_dp[i] += 1;

    // Update dp for next iteration
    dp = next_dp;
    next_dp = List.filled(n, 0); // Reset next_dp for next iteration
  }

  return dp[n - 1];
}
