final int _bitLength = 8;
int get bitLength => _bitLength;

int get maxVal => (1 << bitLength) - 1;

List<int> toBinary(int value) {
  if (value < 0 || value > maxVal) throw ArgumentError('Value out of range');

  final List<int> bits = List.filled(bitLength, 0);
  for (var i = 0; i < bitLength; i++) {
    bits[i] = value & 1;
    value >>= 1;
  }
  return bits;
}

int fromBinary(List<int> binary) {
  var result = 0;
  for (var b in binary.reversed) {
    result <<= 1;
    result |= b;
  }
  return result;
