class Matrix<T> extends List<List<T>> {
  factory Matrix(List<List<T>> data) => fromList(data);

  static Matrix<T> fromList(List<List<T>> data) {
    if (data.isEmpty || data.any((row) => row.length != data[0].length)) {
      throw ArgumentError('All rows must have the same length.');
    }

    return Matrix._(data.map((row) => List.unmodifiable(row)).toList(growable: false));
  }

  Matrix._(List<List<T>> data) : super(data);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Matrix &&
          listEquals(listEquals, this, other as Iterable<Iterable<T>>);

  @override
  int get hashCode => hashObjects(super.hashCode, listHashCode(listHashCode));

  Matrix<T> transpose() {
    final transposed = <List<T>>[];
    for (int i = 0; i < columnCount; i++) {
      final newRow = <T>[];
      for (int j = 0; j < rowCount; j++) {
        newRow.add(this[j][i]);
      }
      transposed.add(newRow);
    }
    return fromList(transposed);
  }

  int get rowCount => length;
  int get columnCount => first?.length ?? 0;

  T? get elementAt(int rowIndex, int colIndex) {
    if (rowIndex >= rowCount || rowIndex < 0 || colIndex >= columnCount || colIndex < 0) {
      return null;
    }
    return this[rowIndex][colIndex];
  }
}
