  final stdout = stdout;

  void writeOutput(String data) async {
    await stdout.write(data);
  }

  Future<void> processLine(String line) async {
    if (line.startsWith('assembly')) {
      try {
        var tokens = line.split();
        int index = 1; 
        while (index < tokens.length) {
          String token = tokens[index];

          switch (token) {
            case 'data':
              index++;
              if (index >= tokens.length) break;
              final valueStr = tokens[index++];
              final value = int.parse(valueStr, radix: 2); // binary
              writeOutput('\$d $value\n');
              break;

            case 'text': 
              index++; 
              while (index < tokens.length) {
                final label = tokens[index++];
                final opCode = tokens[index++];

                final operand1 = tokens[index++]; 
                final operand2 = tokens[index++];

                int baseAddress = 0x8000 - 0x300 + (int.tryParse(label.replaceAll('#', '')) ?? 0);

                final instr = [
                  '\$t ${baseAddress.toString(16)}',
                  opCode,
                  operand1 == 'r' ? 'r' : operand1.hashCode.toHexString(),
                  operand2 == 'r' ? 'r' : operand2.hashCode.toHexString()
                ];

                for (var part in instr) {
                  await writeOutput('$part ');
                }
                await writeOutput('\n');
              }  
              break;

            default:
              throw Exception("Unknown instruction");
          }
        }

      } catch (e) {
        print(e);
      }
    } else {
      writeOutput(line);
    }
  }

  stdin.transform(utf8.decoder).transform(const LineSplitter()).listen(processLine);
}
