    // Spawn an isolate for parallel computation
    final receivePort = ReceivePort();
    final sendPort = Isolate.spawn(
      () => _fibonacciIsolate(receivePort.sendPort),
      [],
    );

    await Future.delayed(Duration(milliseconds: 1));
    sendPort.send([n - 1]);
    var fibNMinusOne = await receivePort.first; 

    await Future.delayed(Duration(milliseconds: 1));
    sendPort.send([n - 2]);
    var fibNMinusTwo = await receivePort.first;

    sendPort.close();
    await receivePort.onClosed.then((_) {});

    return fibNMinusOne + fibNMinusTwo;
  }
}

void _fibonacciIsolate(SendPort sendPort) {
  while (true) {
    final message = ReceivePort().receive(); 
    if (message is List && message.length == 1 && message[0] != null) {
      final num = message[0];
      if (num <= 1) {
        sendPort.send(num);
      } else {
        final port = SendPort();
        final p1 = Isolate.spawn(_fibonacciIsolate, [port]);
        final p2 = Isolate.spawn(_fibonacciIsolate, [port]);

        p1.send([num - 1]);
        p2.send([num - 2]);

        final result1 = p1.receive().first;
        final result2 = p2.receive().first;

        sendPort.send(result1 + result2);
      }
    } else {
      break;
    }
  }
}
