    // Parse instruction
    final parts = line.split(' ');
    final op = parts[0];
    final args = parts.sublist(1).map((arg) => arg.trim()).toList();

    switch(op) {
      case 'mov':
        if (args.length == 2 && args[1] != 'r') { // Immediate move
          result += r'final ${args[0]} = ${args[1]};\n';
        } else {
          result += r'${args[0]} = ${args[1]};\n';
        }

      case 'add':
        if (args.length == 3) {
          result += r'${args[0]} = ${args[1]} + ${args[2]};\n';
        } else {
          throw Exception("Invalid add operation");
        }

      case 'sub':
        if (args.length == 3) {
          result += r'${args[0]} = ${args[1]} - ${args[2]};\n';
        } else {
          throw Exception("Invalid sub operation");
        }

      case 'mul':
        if (args.length == 3) {
          result += r'${args[0]} = ${args[1]} * ${args[2]};\n';
        } else {
          throw Exception("Invalid mul operation");
        }

