    // Parse instruction
    if (line.contains(':=')) {
      handleAssignment(line, output);
    } else if (line.contains('=>')) {
      handleFunctionCall(line, output);
    } else {
      handleExpression(line, output);
    }
  }

  return output.toString();
}

void handleDirective(String line, StringBuffer output) {
