  if (s.isEmpty) return '';

  var stack = <int>[];
  int i = 0;
  while (i < s.length) {
    if (s[i] == '(') {
      stack.add(1);
      i++;
    } else if (s[i] == ')') {
      if (stack.isNotEmpty) {
        stack.removeLast(); // pop the opening parenthesis
        i++;
      } else {
        stack.add(-1); // unmatched closing parenthesis, treat as invalid
        i++;
      }
    } else if (s[i].isDigit) {
      if (stack.isNotEmpty && stack.last != -1) {
        // add to current number
        stack[stack.length - 1] *= 10 + int.parse(s[i]);
      } else {
        stack.add(int.parse(s[i]));
      }
      i++;
    } else {
      throw ArgumentError('Invalid character');
    }
  }

  // Check for any remaining unmatched parentheses or numbers
  if (stack.any((e) => e < 0)) {
    throw FormatException('Unmatched closing parenthesis');
  }

  if (stack.isEmpty) return '';

  String result = stack.map((x) => x.toString()).join('');
  if (result.startsWith('-')) {
    return '-${result.substring(1)}';
  }
  return result;
}
