import 'dart:convert';
import 'dart:math' as math;

String? decrypt(String input, String key) {
  int length = min(input.length, key.length);
  List<int> result = [];

  for (int i = 0; i < length; i++) {
    var ch1 = input.codeUnitAt(i);
    var ch2 = key.codeUnitAt(i % key.length);

    if ((ch1 & 0x80) != 0 || (ch2 & 0x80) != 0) continue;

    var xorResult = ch1 ^ ch2;

    // Check if the resulting byte is printable ASCII (excluding control characters)
    if (xorResult >= 32 && xorResult <= 126) {
      result.add(xorResult);
    }
  }

  return utf8.decode(result).trim();
}

List<String>? parseInput(String text) {
  final lines = text.split('\n').map((line) => line.trim()).toList();

  bool inKeySection = false;
  bool inDataSection = false;
  bool skipNextLine = false;

  List<String?> entries = [];

  for (var line in lines) {
    if (skipNextLine) {
      skipNextLine = false;
      continue;
    }

    if (inKeySection) {
      if (line.startsWith('[')) {
        break;
      }

      if (!line.isEmpty) {
        entries.add(line);
      }
    } else if (line == '[key]') {
      inKeySection = true;
    } else if (line == '[data]') {
      inDataSection = true;
    } else if (line == '[end]') {
      break;
    }
  }

  if (entries.isNotEmpty) {
    return entries.map((e) => e!).toList();
  }
  return null;
}

void main() async {
  try {
    final content = await File('input.txt').readAsString();
    final parsedEntries = parseInput(content);

    if (parsedEntries == null) {
      print("Invalid format");
      return;
    }

    String dataLines = parsedEntries[0];
    String keyLines = parsedEntries[1];

    final dataBytes = utf8.encode(dataLines);
    final keyBytes = utf8.encode(keyLines);

    final decrypted = decrypt(utf8.decode(dataBytes), utf8.decode(keyBytes));

    if (decrypted != null) {
      print(decrypted);
    }
  } catch (e) {
    print(e.toString());
  }
}
